function validateConfigMessage(cfg, update) {
  const message = update?.message;
  if (!message || message.from?.is_bot || !message.chat || message.chat.type !== 'private') return null;
  const bad = value => !String(value || '').trim() || /REPLACE_|YOUR_|APPROVED_FAQ_HERE/.test(String(value));
  if (bad(cfg.spreadsheetId) || !/^[A-Za-z0-9_-]{20,}$/.test(cfg.spreadsheetId)) throw new Error('Configure spreadsheetId before using this template.');
  if (bad(cfg.humanChatId) || !/^-?[0-9]+$/.test(String(cfg.humanChatId))) throw new Error('Configure the private staff humanChatId.');
  if (String(cfg.humanChatId) === String(message.chat.id)) throw new Error('The staff destination must differ from the customer chat.');
  if (bad(cfg.slackChannelId) || !/^[CG][A-Z0-9]{8,}$/.test(cfg.slackChannelId)) throw new Error('Configure the private Slack alert channel.');
  if (bad(cfg.businessName) || bad(cfg.supportContact) || bad(cfg.approvedFaq)) throw new Error('Configure businessName, supportContact, and approvedFaq with reviewed business facts.');
  if (cfg.approvedFaq.length > 24000) throw new Error('Keep approvedFaq below 24000 characters.');
  for (const key of ['classifierModel','fastReplyModel','detailedReplyModel','transcriptionModel']) {
    if (bad(cfg[key])) throw new Error('Configure the Groq model IDs.');
  }
  if (cfg.ttsEnabled && (bad(cfg.ttsModel) || bad(cfg.ttsVoice))) throw new Error('Configure TTS model and voice.');
  if (typeof cfg.storeMessageContent !== 'boolean' || typeof cfg.ttsEnabled !== 'boolean') throw new Error('Privacy and TTS settings must be booleans.');
  if (!Number.isFinite(cfg.minimumConfidence) || cfg.minimumConfidence < 0 || cfg.minimumConfidence > 1) throw new Error('minimumConfidence must be between 0 and 1.');
  if (!Number.isSafeInteger(message.chat.id) || !Number.isSafeInteger(message.from?.id) || !Number.isSafeInteger(message.message_id) || !Number.isSafeInteger(update.update_id)) return null;
  const text = typeof message.text === 'string' ? message.text.trim() : '';
  const voice = message.voice;
  const inputType = voice?.file_id ? 'voice' : text ? 'text' : 'unsupported';
  const voiceAllowed = inputType !== 'voice' || (Number(voice.duration) > 0 && Number(voice.duration) <= 300 && Number(voice.file_size || 0) <= 10 * 1024 * 1024);
  const accepted = inputType !== 'unsupported' && voiceAllowed && text.length <= 8000;
  return { config: cfg, caseId: 'TG-' + update.update_id, messageId: String(message.message_id), chatId: String(message.chat.id),
    userId: String(message.from.id), userName: String(message.from.first_name || 'Customer').slice(0,100),
    inputType: accepted ? inputType : 'unsupported', voiceFileId: voice?.file_id || '',
    transcript: text, intent: 'unclassified', sentiment: 'unknown', securityRisk: false,
    requiresHuman: false, escalated: false, classificationValid: false, confidence: 0,
    lockMinutes: 30, replyText: '', outcome: '', deliveryWarning: '' };
}

const value = validateConfigMessage($input.first().json, $('Telegram Message').first().json);
return value ? [{json:value}] : [];

function evaluateLock(rows, context, nowMs) {
  const matching = rows.filter(row => String(row.chatId ?? '').trim() === context.chatId && String(row.status || '').toLowerCase() === 'open');
  let invalidLock = false;
  const isLocked = matching.some(row => {
    const start = Date.parse(row.escalatedAt), end = Date.parse(row.lockExpiresAt);
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start || end - start !== 30 * 60000 || start > nowMs) { invalidLock = true; return false; }
    return nowMs < end;
  });
  return {...context, isLocked, invalidLock};
}

// alwaysOutputData also emits an empty success item after a read error. Only the explicit error branch may continue in that case.
let readErrors=[]; try { readErrors=$('Read Chat Escalation Lock').all(1); } catch {}
if(readErrors.length) return [];
return [{json:evaluateLock($input.all().map(i=>i.json), $('Validate Configuration & Message').first().json, Date.now())}];

function parseClassification(payload, context) {
  const fail = reason => ({...context, classificationValid: false, requiresHuman: true, intent: 'other', sentiment: 'unknown', securityRisk: false, confidence: 0, escalationReason: reason});
  let value;
  try {
    const raw = payload?.choices?.[0]?.message?.content;
    if (typeof raw !== 'string' || raw.length > 8000 || payload.choices[0].finish_reason !== 'stop') return fail('invalid_classifier_response');
    value = JSON.parse(raw.trim());
  } catch { return fail('invalid_classifier_json'); }
  const intents = ['faq','how_to','technical_issue','account_request','security_issue','other'];
  const sentiments = ['neutral','frustrated','angry'];
  if (!value || Array.isArray(value) || !intents.includes(value.intent) || !sentiments.includes(value.sentiment) ||
      typeof value.security_risk !== 'boolean' || typeof value.needs_human !== 'boolean' ||
      typeof value.confidence !== 'number' || !Number.isFinite(value.confidence) || value.confidence < 0 || value.confidence > 1) return fail('invalid_classifier_schema');
  const reasons = [];
  if (context.invalidLock) reasons.push('invalid_lock_record');
  if (value.needs_human) reasons.push('human_requested_or_needed');
  if (value.security_risk || value.intent === 'security_issue') reasons.push('security_review');
  if (['angry','frustrated'].includes(value.sentiment)) reasons.push('customer_needs_attention');
  if (['account_request','other'].includes(value.intent)) reasons.push('outside_approved_self_service');
  if (value.confidence < context.config.minimumConfidence) reasons.push('low_classifier_confidence');
  return {...context, classificationValid: true, intent: value.intent, sentiment: value.sentiment,
    securityRisk: value.security_risk, confidence: value.confidence,
    requiresHuman: reasons.length > 0, escalationReason: reasons.join(', ') || ''};
}

let context; try { context=$('Extract Voice Transcript').first().json; } catch { context=$('Extract Text Transcript').first().json; }
return [{json:parseClassification($input.first().json, context)}];

function parseReply(payload, context) {
  const fail = reason => ({...context, requiresHuman: true, escalationReason: reason});
  try {
    const choice = payload?.choices?.[0];
    if (choice?.finish_reason !== 'stop' || typeof choice?.message?.content !== 'string') return fail('incomplete_reply_response');
    const value = JSON.parse(choice.message.content.trim());
    if (!value || typeof value.needs_human !== 'boolean' || typeof value.reply !== 'string') return fail('invalid_reply_schema');
    if (value.needs_human || !value.reply.trim()) return fail('answer_not_supported_by_approved_faq');
    if (value.reply.length > 3500) return fail('reply_too_long');
    return {...context, replyText: value.reply.trim(), requiresHuman: false, outcome: 'automated_faq_reply'};
  } catch { return fail('invalid_reply_json'); }
}

return [{json:parseReply($input.first().json,$('Validate Classification JSON').first().json)}];

function interactionLog(context, deliveryStatus, now) {
  const content = context.config.storeMessageContent;
  return { timestamp: now, caseId: context.caseId, chatId: context.chatId, inputType: context.inputType,
    userName: content ? context.userName : '[not stored]', transcript: content ? context.transcript : '[not stored]',
    intent: context.intent, sentiment: context.sentiment, securityRisk: String(context.securityRisk),
    escalated: String(context.escalated), outcome: context.outcome, deliveryStatus,
    deliveryWarning: context.deliveryWarning || '', reply: content ? context.replyText : '[not stored]' };
}

return [{json:interactionLog($('Prepare Delivery').first().json,'speech_attachment_sent',new Date().toISOString())}];

function interactionLog(context, deliveryStatus, now) {
  const content = context.config.storeMessageContent;
  return { timestamp: now, caseId: context.caseId, chatId: context.chatId, inputType: context.inputType,
    userName: content ? context.userName : '[not stored]', transcript: content ? context.transcript : '[not stored]',
    intent: context.intent, sentiment: context.sentiment, securityRisk: String(context.securityRisk),
    escalated: String(context.escalated), outcome: context.outcome, deliveryStatus,
    deliveryWarning: context.deliveryWarning || '', reply: content ? context.replyText : '[not stored]' };
}

let context=$('Prepare Delivery').first().json; try { const fallback=$('Prepare Speech Text Fallback').first().json; context={...context,deliveryWarning:fallback.deliveryWarning}; } catch {} return [{json:interactionLog(context,'text_sent',new Date().toISOString())}];

function htmlEscape(text) { return String(text ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

const c=$('Validate Configuration & Message').first().json;
const stage=String($prevNode.name || 'unknown');
const error=$input.first().json.error || {};
const raw=typeof error==='string'?error:String(error.message||'');
const status=Number(error.httpCode||error.statusCode||0);
const errorCategory=status===401||status===403?'authentication_or_permission':status===429?'rate_limit':/timeout|network|connect|socket/i.test(raw)?'network_or_timeout':'operation_failed';
const skipUserFallback=['Send Text Reply','Log Interaction'].includes(stage);
const reply='I could not finish processing this message. Please use '+c.config.supportContact+' or try again later. This workflow cannot guarantee a staff response.';
return [{json:{caseId:c.caseId,chatId:c.chatId,inputType:c.inputType,stage,errorCategory,timestamp:new Date().toISOString(),skipUserFallback,replyHtml:htmlEscape(reply)}}];

